const $=id=>document.getElementById(id);let docs=[],current=null,pageIndex=0,tab='statement',renderVersion=0,editField=null,busy=false;let toastTimer;
function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),5000)}
const el=(tag,cls,text)=>{let n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const active=()=>docs.find(d=>d.id===current);const dateFormat=()=>$('date-format').value;
let dbPromise=new Promise((resolve,reject)=>{let r=indexedDB.open('pci-pdf-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('documents',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});dbPromise.catch(()=>{});
