function save(doc){const {pdf,history,correctedBytes,correctedSignature,...data}=doc;db('put',structuredClone(data)).catch(()=>toast('No se pudo guardar en este dispositivo. Exporta tus cambios antes de cerrar.'))}
async function ensurePdf(doc){if(doc.pdf)return doc.pdf;if(doc.bytes){doc.pdf=await pdfjs.getDocument({data:doc.bytes.slice(),useSystemFonts:true}).promise;return doc.pdf}return null}
function changes(doc){return doc.pages.flatMap(p=>p.fields).filter(f=>f.value!==f.original).length+doc.rows.filter(r=>!r.fields.date&&!r.fields.amount&&!r.fields.deposit&&!r.fields.debit&&r.dirty).length}
function render(){const d=active();$('stat-docs').replaceChildren(document.createTextNode(String(docs.length)+' '),el('small','', 'en este espacio'));$('stat-rows').replaceChildren(document.createTextNode(String(docs.reduce((s,d)=>s+d.rows.length,0))+' '),el('small','','para revisar'));$('stat-changes').replaceChildren(document.createTextNode(String(docs.reduce((s,d)=>s+changes(d),0))+' '),el('small','','listos para exportar'));$('stat-total').textContent=money(d?totals(d).total:0);$('stat-total').parentElement.querySelector('span').textContent=d?.bank?'SALDO FINAL CALCULADO':'TOTAL DEL STATEMENT';$('doc-count').textContent=docs.length;$('current-name').textContent=d?.name||'Sin documento';$('add-row').disabled=!!d?.bytes;$('add-row').title=d?.bytes?'El PDF original solo permite corregir fechas e importes.':'';$('table-meta').textContent=d?`${d.rows.length} movimientos · ${d.bank?'Depósitos y retiros':'Cantidad × precio'}`:'Importa un PDF o añade tus movimientos.';$('doc-list').replaceChildren();
 for(const doc of docs){let item=el('div','doc'+(doc.id===current?' active':''));let select=el('button','doc-select');select.style.cssText='display:flex;align-items:center;gap:9px;border:0;padding:0;background:none;flex:1;min-width:0;text-align:left';let icon=el('span','filetype red','PDF'),text=el('div','doc-text');text.append(el('div','doc-name',doc.name),el('small','',`${doc.pages.length||1} pág. · ${changes(doc)} cambios`));select.append(icon,text);select.onclick=()=>{current=doc.id;pageIndex=0;render()};let del=el('button','remove-doc','×');del.setAttribute('aria-label',`Quitar ${doc.name}`);del.onclick=()=>{if(!confirm('¿Quitar este documento y sus cambios del dispositivo?'))return;doc.pdf?.destroy();docs=docs.filter(d=>d.id!==doc.id);db('delete',doc.id).catch(()=>{});if(current===doc.id){current=docs[0]?.id||null;pageIndex=0}render()};item.append(select,del);$('doc-list').append(item)}
 const th=document.querySelector('thead tr');th.children[3].textContent=d?.bank?'Depósitos':'Cantidad';th.children[4].textContent=d?.bank?'Retiros':'Precio / importe';th.children[5].textContent=d?.bank?'Saldo':'Total';$('rows').replaceChildren();$('empty').hidden=!!d?.rows.length;$('select-all').checked=!!d?.rows.length&&d.rows.every(r=>r.selected);$('select-all').indeterminate=!!d?.rows.some(r=>r.selected)&&!d.rows.every(r=>r.selected);
 if(d){recalc(d,false);for(const r of d.rows){let tr=el('tr');tr.dataset.row=r.id;let td=el('td'),check=el('input');check.type='checkbox';check.checked=r.selected;check.setAttribute('aria-label','Seleccionar movimiento');check.onchange=()=>{r.selected=check.checked;renderSelection();save(d)};td.append(check);tr.append(td);
  function inputCell(key,type,opts={}){let td=el('td'),i=el('input');i.type=type;i.value=r[key]??'';i.setAttribute('aria-label',key==='description'?'Descripción':key==='date'?'Fecha':key==='deposit'?'Depósito':key==='debit'?'Retiro':key==='qty'?'Cantidad':'Precio');if(type==='number'){i.step=key==='qty'?'0.001':'0.01';if(d.bank||key==='qty')i.min='0'}if(opts.disabled)i.disabled=true;i.title=opts.disabled?'Esta columna no contiene un importe en el PDF original.':'';i.onchange=()=>{let value=type==='number'?Number(i.value):i.value;if(!i.validity.valid||type==='number'&&!Number.isFinite(value)){toast('Introduce un valor válido.');i.value=r[key];return}snapshot(d);try{r[key]=value;syncRow(d,r,key,dateFormat());save(d);render()}catch(e){undo(d);render();toast(e.message)}};td.append(i);tr.append(td)}
  inputCell('date','date');inputCell('description','text',{disabled:!!d.bytes});inputCell(d.bank?'deposit':'qty','number',{disabled:!!d.bytes&&(!d.bank||!r.fields.deposit)});inputCell(d.bank?'debit':'price','number',{disabled:d.bank&&d.bytes&&!r.fields.debit&&!!r.fields.date});tr.append(el('td','row-total',money(d.bank?r.calculatedBalance:round(r.qty*r.price))));let action=el('td'),del=el('button','delete-row','×');del.setAttribute('aria-label','Eliminar movimiento');del.disabled=!!d.bytes;del.onclick=()=>{if(!confirm('¿Eliminar este movimiento? Se quitará de los cálculos y de la copia exportada.'))return;snapshot(d);for(const v of Object.values(r.fields))for(const id of Array.isArray(v)?v:[v]){let f=getField(d,id);if(f)f.value=''}d.rows=d.rows.filter(x=>x!==r);recalc(d);save(d);render()};action.append(del);tr.append(action);$('rows').append(tr)}
 }
 $('table-total').textContent=money(d?totals(d).total:0);$('table-total').previousElementSibling.textContent=d?.bank?'Saldo final':'Total calculado';renderSelection();renderBankSummary(d);$('undo').disabled=!d?.history?.length;$('review-note').textContent=d?.bank?'Solo se corrigen fechas e importes. Los saldos y totales se recalculan con la tipografía y el diseño originales.':'Revisa los campos detectados. En un PDF original solo se pueden corregir fechas e importes.';if(tab==='pdf')renderPdf();
}
function renderSelection(){const d=active();$('selection-count').textContent=`${d?.rows.filter(r=>r.selected).length||0} filas seleccionadas`;if(d){$('select-all').checked=!!d.rows.length&&d.rows.every(r=>r.selected);$('select-all').indeterminate=d.rows.some(r=>r.selected)&&!d.rows.every(r=>r.selected)}}
function renderBankSummary(d){let old=$('bank-summary');if(old)old.remove();if(!d?.bank)return;let box=el('div','bank-summary');box.id='bank-summary';let label=el('label','','Saldo inicial '),input=el('input');input.type='number';input.step='.01';input.value=d.opening;input.setAttribute('aria-label','Saldo inicial');input.onchange=()=>{if(!input.validity.valid||!Number.isFinite(+input.value))return;snapshot(d);d.opening=+input.value;recalc(d);save(d);render()};label.append(input);let t=totals(d);box.append(label,el('span','',`Depósitos ${money(t.deposits)}`),el('span','',`Retiros ${money(t.debits)}`));$('statement-view').insertBefore(box,$('table-footer'))}
async function importFiles(files){if(busy){toast('Espera a que termine la importación.');return}busy=true;$('connection').textContent='Importando PDFs…';let imported=0;try{for(const file of files){if(!file.name.toLowerCase().endsWith('.pdf')){toast('Selecciona archivos PDF.');continue}if(file.size>25*1024*1024){toast(`${file.name}: supera el límite de 25 MB.`);continue}let pdf;try{toast(`Importando ${file.name}…`);let bytes=new Uint8Array(await file.arrayBuffer());pdf=await pdfjs.getDocument({data:bytes.slice(),useSystemFonts:true}).promise;if(pdf.numPages>100){await pdf.destroy();throw Error('El máximo es de 100 páginas por PDF.')}let pages=[];for(let n=1;n<=pdf.numPages;n++){const p=await pdf.getPage(n),vp=p.getViewport({scale:1}),text=await p.getTextContent();pages.push({index:n-1,width:vp.width,height:vp.height,fields:fieldsFromText(text,vp,n-1,pdfjs.Util)})}let doc=parseDocument(pages,dateFormat());doc.name=file.name;doc.bytes=bytes;doc.pdf=pdf;doc.history=[];recalc(doc,false);docs.push(doc);current=doc.id;pageIndex=0;save(doc);imported++;render();if(!pages.some(p=>p.fields.length))toast('Este PDF parece escaneado. La vista PDF funciona; añade los movimientos manualmente. No incluye OCR.');else if(!doc.rows.length)toast('No se detectaron movimientos. Puedes editar textos en Vista PDF o añadir filas.')}catch(e){pdf?.destroy();toast(e.name==='PasswordException'?'El PDF está protegido. Importa una copia sin contraseña.':`No se pudo importar ${file.name}: ${e.message}`)}}if(imported)toast(`${imported} documento(s) importado(s). Revisa los datos detectados.`)}finally{busy=false;$('connection').textContent=navigator.onLine?'Guardado en este dispositivo':'Sin conexión · guardado en este dispositivo';$('pdf-input').value=''}}
$('pdf-input').onchange=e=>importFiles([...e.target.files]);let drop=$('dropzone');for(const event of ['dragenter','dragover'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('drag')});for(const event of ['dragleave','drop'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('drag')});drop.addEventListener('drop',e=>importFiles([...e.dataTransfer.files]));
function setTab(value){tab=value;$('statement-view').hidden=value!=='statement';$('pdf-view').hidden=value!=='pdf';for(const v of ['statement','pdf']){$('tab-'+v).classList.toggle('active',v===value);$('tab-'+v).setAttribute('aria-selected',v===value)}if(value==='pdf')renderPdf()}
$('tab-statement').onclick=()=>setTab('statement');$('tab-pdf').onclick=()=>setTab('pdf');$('select-all').onchange=e=>{const d=active();if(d){d.rows.forEach(r=>r.selected=e.target.checked);save(d);render()}};
$('apply-date').onclick=()=>{const ds=$('batch-scope').value==='all'?docs:[active()].filter(Boolean),iso=$('batch-date').value,selected=$('batch-scope').value==='selected';if(!ds.length){toast('Importa un documento primero.');return}if(!isoDate(iso)){toast('Elige una fecha válida.');return}if(selected&&!ds.some(d=>d.rows.some(r=>r.selected))){toast('Selecciona al menos una fila.');return}let count=0;for(const d of ds){snapshot(d);count+=applyBatchDate(d,iso,dateFormat(),selected);save(d)}render();toast(`Fecha aplicada. ${count} campos del PDF actualizados.`)};
$('date-format').onchange=()=>{try{localStorage.setItem('pci-date-format',dateFormat())}catch{};for(const d of docs)for(const r of d.rows){let f=getField(d,r.fields.date);if(f){let v=isoDate(f.value,d.year,dateFormat());if(v)r.date=v}}render()};try{$('date-format').value=localStorage.getItem('pci-date-format')||'MDY'}catch{}
$('undo').onclick=()=>{let d=active();if(d&&undo(d)){save(d);render();toast('Cambio deshecho.')}};
function manualDoc(name='Statement nuevo'){return {id:crypto.randomUUID(),name,pages:[],rows:[],bank:false,opening:0,summary:{},history:[],year:new Date().getFullYear()}}
$('add-row').onclick=()=>{let d=active();if(!d){d=manualDoc();docs.push(d);current=d.id}snapshot(d);d.rows.push({id:crypto.randomUUID(),date:'',description:'Nuevo movimiento',...(d.bank?{deposit:0,debit:0}:{qty:1,price:0}),fields:{},selected:false,dirty:true});recalc(d);save(d);render()};
$('demo').onclick=()=>{let d=manualDoc('Ejemplo · statement PCI');d.rows=[['2026-09-16','Estacionamiento · turno matutino',12,20],['2026-09-16','Estacionamiento · turno vespertino',8,25],['2026-09-17','Pase mensual',3,150]].map(([date,description,qty,price])=>({id:crypto.randomUUID(),date,description,qty,price,fields:{},selected:false,dirty:false}));docs.push(d);current=d.id;save(d);render();toast('Ejemplo cargado. Puedes editar cualquier fila.')};

async function correctedBytes(doc){let signature=doc.pages.flatMap(p=>p.fields).filter(f=>f.value!==f.original).map(f=>f.id+'='+f.value).join('|');if(doc.correctedSignature===signature&&doc.correctedBytes)return doc.correctedBytes;const bytes=await editOriginalPDF(doc.bytes,doc.pages,PDFLib);doc.correctedSignature=signature;doc.correctedBytes=bytes;return bytes}
async function pageCanvas(doc,index,scale=1.5){await ensurePdf(doc);let pdf=doc.pdf,temp;const hasChanges=doc.pages.some(p=>p.fields.some(f=>f.value!==f.original));if(hasChanges){temp=await pdfjs.getDocument({data:(await correctedBytes(doc)).slice(),useSystemFonts:true}).promise;pdf=temp}try{let page=await pdf.getPage(index+1),vp=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.ceil(vp.width);canvas.height=Math.ceil(vp.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;return canvas}finally{if(temp)await temp.destroy()}}
async function renderPdf(){let version=++renderVersion,d=active();$('pdf-stage').replaceChildren(el('div','pdf-empty',d?.bytes?'Cargando página…':'Importa un PDF para editar sus campos.'));$('prev-page').disabled=pageIndex===0;$('next-page').disabled=!d||pageIndex>=d.pages.length-1;$('page-label').textContent=d?.pages.length?`${pageIndex+1} / ${d.pages.length}`:'Sin páginas';if(!d?.bytes)return;try{const canvas=await pageCanvas(d,pageIndex,1.5);if(version!==renderVersion)return;let p=d.pages[pageIndex],container=el('div','pdf-page');container.style.width=`${p.width}px`;container.append(canvas);for(const f of p.fields){if(!isMoney(f.original)&&!f.original.match(datePattern))continue;let hit=el('button','text-hit'+(f.value!==f.original?' changed':''));hit.style.cssText=`left:${f.x/p.width*100}%;top:${f.top/p.height*100}%;width:${f.width/p.width*100}%;height:${f.height/p.height*100}%`;hit.title=f.value||'(campo eliminado)';hit.setAttribute('aria-label',`Editar ${f.value||f.original}`);hit.onclick=()=>openField(d,f);container.append(hit)}$('pdf-stage').replaceChildren(container)}catch(e){if(version===renderVersion)$('pdf-stage').replaceChildren(el('div','pdf-empty','No se pudo mostrar esta página.'));toast(e.message)}}
$('prev-page').onclick=()=>{if(pageIndex>0){pageIndex--;renderPdf()}};$('next-page').onclick=()=>{if(pageIndex<(active()?.pages.length||0)-1){pageIndex++;renderPdf()}};
function openField(doc,f){let isDerived=Object.entries(doc.summary).some(([key,id])=>id===f.id&&key!=='opening')||doc.rows.some(r=>r.fields.balance===f.id);if(isDerived){toast('Este total se calcula automáticamente. Edita los importes de los movimientos.');return}editField={doc,f};$('field-original').value=f.original;$('field-value').value=f.value;$('field-dialog').showModal();$('field-value').focus()}
$('field-close').onclick=()=>$('field-dialog').close();$('field-reset').onclick=()=>{$('field-value').value=editField.f.original};$('field-form').onsubmit=e=>{e.preventDefault();const {doc,f}=editField;let value=$('field-value').value;if(!isMoney(f.original)){const oldDates=f.original.match(datePattern)||[],newDates=value.match(datePattern)||[];if(!oldDates.length||oldDates.length!==newDates.length||f.original.replace(datePattern,'').trim()!==value.replace(datePattern,'').trim()||newDates.some(v=>!isoDate(v,doc.year,dateFormat()))){toast('Solo puedes corregir las fechas de este campo. Conserva el resto del texto.');return}}let numeric=doc.summary.opening===f.id||doc.rows.some(r=>[r.fields.deposit,r.fields.debit,r.fields.amount].includes(f.id));if((numeric||isMoney(f.original))&&!Number.isFinite(amount(value))){toast('Introduce un importe válido, por ejemplo 1,250.00.');return}if(doc.rows.some(r=>[r.fields.deposit,r.fields.debit].includes(f.id))&&amount(value)<0){toast('Usa un importe positivo en depósitos o retiros.');return}if(doc.rows.some(r=>r.fields.date===f.id)&&!isoDate(value,doc.year,dateFormat())){toast('Introduce una fecha válida con el formato seleccionado.');return}snapshot(doc);f.value=value;for(const r of doc.rows){if(r.fields.date===f.id)r.date=isoDate(value,doc.year,dateFormat());for(const k of ['deposit','debit'])if(r.fields[k]===f.id)r[k]=amount(value);if(r.fields.amount===f.id){r.price=amount(value);r.qty=1}if(r.fields.description?.includes(f.id))r.description=r.fields.description.map(id=>getField(doc,id).value).join(' ')}if(doc.summary.opening===f.id)doc.opening=amount(value);if(numeric)recalc(doc);save(doc);$('field-dialog').close();render();toast('Campo actualizado.')};
let preparedDownload=null;
function clearDownload(){preparedDownload?.dispose();preparedDownload=null;$('download-ready').hidden=true;$('export-error').hidden=true;$('download-link').removeAttribute('href');$('open-file-link').removeAttribute('href')}
function download(content,name,type){preparedDownload?.dispose();preparedDownload=prepareDownload(content,name,type);$('download-name').textContent=name;$('download-link').href=preparedDownload.url;$('download-link').download=name;$('open-file-link').href=preparedDownload.url;$('share-file').hidden=!navigator.canShare?.({files:[preparedDownload.file]});$('save-file').hidden=typeof window.showSaveFilePicker!=='function';$('download-ready').hidden=false;$('export-error').hidden=true;$('download-link').focus()}
$('share-file').onclick=async()=>{if(!preparedDownload)return;try{await shareDownload(preparedDownload.file)}catch(e){if(e.name!=='AbortError')toast(e.message)}};
$('save-file').onclick=async()=>{if(!preparedDownload)return;const item=preparedDownload;try{const handle=await window.showSaveFilePicker({suggestedName:item.name});const writable=await handle.createWritable();await writable.write(item.file);await writable.close();toast('Archivo guardado.')}catch(e){if(e.name!=='AbortError')toast('No se pudo guardar. Usa Descargar archivo o Abrir archivo.')}};
$('download-link').onclick=()=>{$('download-help').textContent='Si no aparece la descarga, pulsa Abrir archivo y guárdalo desde el navegador. También puedes abrir esta app en tu navegador habitual.'};
window.addEventListener('pagehide',()=>preparedDownload?.dispose());

async function appendRowsPdf(pdf,doc,rows,label){if(!rows.length)return;let font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica),bold=await pdf.embedFont(PDFLib.StandardFonts.HelveticaBold),page,y;const safe=s=>String(s).replace(/[^\x20-\x7e\xa0-\xff]/g,'?');function newPage(){page=pdf.addPage([612,792]);y=744;page.drawText('PCI · PDF Studio',{x:38,y,size:15,font:bold,color:PDFLib.rgb(.07,.22,.18)});y-=27;page.drawText(safe(label),{x:38,y,size:12,font:bold});y-=20;page.drawText(safe(doc.name).slice(0,85),{x:38,y,size:9,font});y-=26}newPage();for(const r of rows){if(y<65)newPage();let date=r.date||'Sin fecha',desc=safe(r.description);let nums=doc.bank?`+ ${money(r.deposit)}  - ${money(r.debit)}  = ${money(r.calculatedBalance)}`:`${r.qty} x ${money(r.price)} = ${money(round(r.qty*r.price))}`;page.drawText(safe(date+'   '+nums),{x:38,y,size:10,font:bold});y-=16;let chunks=[];while(desc.length){let n=Math.min(95,desc.length);while(font.widthOfTextAtSize(desc.slice(0,n),9)>530)n--;chunks.push(desc.slice(0,n));desc=desc.slice(n)}for(const line of chunks){if(y<55)newPage();page.drawText(line,{x:38,y,size:9,font});y-=13}y-=13}if(y<65)newPage();page.drawText(safe((doc.bank?'Saldo final: ':'Total: ')+money(totals(doc).total)),{x:38,y,size:12,font:bold})}
async function exportPDF(){const d=active();if(!d)throw Error('Importa un PDF primero.');let bytes;if(d.bytes){toast('Preparando copia con las fuentes originales…');bytes=await correctedBytes(d)}else{let pdf=await PDFLib.PDFDocument.create();await appendRowsPdf(pdf,d,d.rows,'Statement');bytes=await pdf.save()}download(bytes,d.name.replace(/\.pdf$/i,'')+'-corregido.pdf','application/pdf')}
$('export-open').onclick=()=>{if(!docs.length){toast('Importa un PDF o añade movimientos primero.');return}clearDownload();$('export-dialog').showModal()};for(const b of document.querySelectorAll('[data-export]'))b.onclick=async()=>{if(busy){toast('Espera a que termine la operación actual.');return}busy=true;clearDownload();const buttons=[...document.querySelectorAll('[data-export]')];buttons.forEach(button=>button.disabled=true);$('export-progress').hidden=false;try{let type=b.dataset.export;if(type==='pdf')await exportPDF();else{let data=exportRows(docs);download(type==='csv'?csvText(data):xlsText(data),`PCI-statements.${type}`,type==='csv'?'text/csv;charset=utf-8':'application/vnd.ms-excel;charset=utf-8')}toast('Archivo listo. Pulsa Descargar archivo.')}catch(e){$('export-error').textContent=e.message;$('export-error').hidden=false;toast(e.message)}finally{busy=false;buttons.forEach(button=>button.disabled=false);$('export-progress').hidden=true}};

$('logos').onclick=()=>$('logo-input').click();function renderLogos(urls){$('brandmark').replaceChildren();for(const url of urls){let i=el('img');i.src=url;i.alt='Logo PCI';$('brandmark').append(i)}}$('logo-input').onchange=async e=>{const files=[...e.target.files].slice(0,2);if(!files.length)return;const urls=[];for(const f of files){if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>2*1024*1024){toast('Usa PNG o JPG de hasta 2 MB por logo.');return}urls.push(await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)}))}try{localStorage.setItem('pci-logos',JSON.stringify(urls));renderLogos(urls);toast('Logos guardados en este dispositivo.')}catch{toast('No se pudieron guardar los logos.')}};try{const urls=JSON.parse(localStorage.getItem('pci-logos')||'[]');if(urls.length)renderLogos(urls)}catch{}
let installPrompt;const standalone=isStandalone();$('install').hidden=standalone;
function showInstallHelp(status){$('install-url').value=new URL('./',location.href).href;$('install-status').textContent=status||'Instala la app desde el navegador de tu dispositivo.';const platform=installationPlatform(navigator.userAgent,navigator.platform,navigator.maxTouchPoints);for(const p of ['ios','android','desktop'])$('install-'+p).open=p===platform;$('install-dialog').showModal()}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});
$('install').onclick=async()=>{if(isStandalone()){toast('Ya estás usando la app instalada.');return}if(!installPrompt){showInstallHelp();return}const prompt=installPrompt;installPrompt=null;try{await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted')toast('Instalación solicitada. Revisa el inicio de tu dispositivo.');else showInstallHelp('Puedes instalarla cuando quieras desde el menú del navegador.')}catch{showInstallHelp('Usa el menú de Safari o Chrome para instalar la app.')}};
$('copy-install-url').onclick=async()=>{try{await navigator.clipboard.writeText($('install-url').value);toast('Enlace copiado. Ábrelo en Safari o Chrome.')}catch{$('install-url').focus();$('install-url').select();toast('Selecciona y copia el enlace para abrirlo en tu navegador.')}};
window.addEventListener('appinstalled',()=>{$('install').hidden=true;$('install-dialog').close();toast('Aplicación instalada.')});
if('serviceWorker'in navigator){let hadController=!!navigator.serviceWorker.controller,refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&!refreshing){refreshing=true;location.reload()}});navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{})};for(const ev of ['online','offline'])window.addEventListener(ev,()=>{$('connection').textContent=navigator.onLine?'Guardado en este dispositivo':'Sin conexión · guardado en este dispositivo'});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_statement_totals',description:'Read document names, movement counts and calculated statement totals.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({documents:docs.map(d=>({id:d.id,name:d.name,movements:d.rows.length,...totals(d)}))})})}catch{}}
render();try{const data=await db('getAll');for(const d of data){d.history=[];docs.push(d)}if(docs.length){current=docs[0].id;render();$('connection').textContent='Guardado en este dispositivo'}}catch{toast('El almacenamiento local no está disponible. Exporta antes de cerrar.')}
